import (
	"context"
	"fmt"
	"io"
	"time"

	workspacev1 "github.com/NerdMeNot/flint/protogen/workspace/v1"
	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/credentials/insecure"
	"google.golang.org/grpc/metadata"
	"google.golang.org/grpc/status"
)

const (
	// wsTokenHeader is the metadata key used to authenticate against the
	// workspace agent. Value must match the run-scoped token.
	wsTokenHeader = "x-flint-ws-token"

	// putChunkSize is the maximum number of bytes sent per Put stream message.
	// 256 KiB balances throughput against per-message overhead.
	putChunkSize = 256 * 1024
)

// RemoteFS is a gRPC-backed FS that talks to the per-run workspace agent pod.
// It implements FS and io.Closer.
//
// RemoteFS uses WaitForReady semantics on every call so that init containers
// can tolerate the brief window between pod scheduling and the workspace
// server accepting connections. The outer context deadline governs the
// maximum wait time.
//
// RemoteFS is safe for concurrent use.
type RemoteFS struct {
	conn   *grpc.ClientConn
	client workspacev1.WorkspaceServiceClient
	token  string
}

// NewRemote dials addr and returns a RemoteFS authenticated with token.
// The connection is established lazily; use WaitForReady on calls or rely on
// context deadlines for startup tolerance.
func NewRemote(addr, token string) (*RemoteFS, error) {
	conn, err := grpc.NewClient(addr,
		grpc.WithTransportCredentials(insecure.NewCredentials()),
	)
	if err != nil {
		return nil, fmt.Errorf("wsfs/remote: dial %s: %w", addr, err)
	}
	return &RemoteFS{
		conn:   conn,
		client: workspacev1.NewWorkspaceServiceClient(conn),
		token:  token,
	}, nil
}

// Close releases the underlying gRPC connection.
func (r *RemoteFS) Close() error {
	return r.conn.Close()
}

// withToken injects the workspace auth token into the outgoing context.
func (r *RemoteFS) withToken(ctx context.Context) context.Context {
	return metadata.AppendToOutgoingContext(ctx, wsTokenHeader, r.token)
}

// waitReady returns the standard call option that blocks until the server is
// ready. This is essential for init containers that start in parallel with
// the workspace pod.
func waitReady() grpc.CallOption {
	return grpc.WaitForReady(true)
}

// Open implements FS. Initiates a server-streaming Get RPC and returns a
// reader that pulls chunks on demand.
func (r *RemoteFS) Open(ctx context.Context, name string) (io.ReadCloser, error) {
	ctx = r.withToken(ctx)
	stream, err := r.client.Get(ctx,
		&workspacev1.GetRequest{Path: name},
		waitReady(),
	)
	if err != nil {
		return nil, mapGRPCError("open", name, err)
	}
	return &getReader{stream: stream}, nil
}

// Create implements FS. Opens a client-streaming Put RPC, sends the path as
// the first message, and returns a writer that streams content chunks.
// The server commits the file when Close is called (CloseAndRecv).
func (r *RemoteFS) Create(ctx context.Context, name string) (io.WriteCloser, error) {
	ctx = r.withToken(ctx)
	stream, err := r.client.Put(ctx, waitReady())
	if err != nil {
		return nil, fmt.Errorf("wsfs/remote: open put stream for %q: %w", name, err)
	}
	// First message declares the destination path.
	if err := stream.Send(&workspacev1.PutRequest{
		Data: &workspacev1.PutRequest_Path{Path: name},
	}); err != nil {
		return nil, fmt.Errorf("wsfs/remote: send path %q: %w", name, err)
	}
	return &putWriter{stream: stream, name: name}, nil
}

// Stat implements FS.
func (r *RemoteFS) Stat(ctx context.Context, name string) (FileInfo, error) {
	ctx = r.withToken(ctx)
	resp, err := r.client.Stat(ctx,
		&workspacev1.StatRequest{Path: name},
		waitReady(),
	)
	if err != nil {
		return FileInfo{}, mapGRPCError("stat", name, err)
	}
	return FileInfo{
		Name:    resp.Name,
		Size:    resp.Size,
		ModTime: timeFromUnix(resp.ModTimeUnix),
		IsDir:   resp.IsDir,
	}, nil
}

// ReadDir implements FS.
func (r *RemoteFS) ReadDir(ctx context.Context, dir string) ([]DirEntry, error) {
	ctx = r.withToken(ctx)
	resp, err := r.client.ReadDir(ctx,
		&workspacev1.ReadDirRequest{Path: dir},
		waitReady(),
	)
	if err != nil {
		return nil, mapGRPCError("readdir", dir, err)
	}
	entries := make([]DirEntry, 0, len(resp.Entries))
	for _, e := range resp.Entries {
		entries = append(entries, DirEntry{
			Name:  e.Name,
			IsDir: e.IsDir,
			Size:  e.Size,
		})
	}
	return entries, nil
}

// MkdirAll implements FS.
func (r *RemoteFS) MkdirAll(ctx context.Context, dir string) error {
	ctx = r.withToken(ctx)
	_, err := r.client.MkdirAll(ctx,
		&workspacev1.MkdirAllRequest{Path: dir},
		waitReady(),
	)
	if err != nil {
		return fmt.Errorf("wsfs/remote: mkdirall %q: %w", dir, err)
	}
	return nil
}

// GetManifest implements ManifestFS.
func (r *RemoteFS) GetManifest(ctx context.Context) (Manifest, int64, error) {
	ctx = r.withToken(ctx)
	resp, err := r.client.GetManifest(ctx,
		&workspacev1.GetManifestRequest{},
		waitReady(),
	)
	if err != nil {
		return nil, 0, fmt.Errorf("wsfs/remote: get manifest: %w", err)
	}
	m := make(Manifest, len(resp.Entries))
	for _, e := range resp.Entries {
		m[e.Path] = ManifestEntry{
			Hash:  e.Hash,
			Size:  e.Size,
			Mtime: e.MtimeUnix,
		}
	}
	return m, resp.Version, nil
}

// Remove implements FS.
func (r *RemoteFS) Remove(ctx context.Context, name string) error {
	ctx = r.withToken(ctx)
	_, err := r.client.Remove(ctx,
		&workspacev1.RemoveRequest{Path: name},
		waitReady(),
	)
	if err != nil {
		return mapGRPCError("remove", name, err)
	}
	return nil
}

// ─────────────────────────────────────────────────────────────
// putWriter — client-side streaming writer for Put
// ─────────────────────────────────────────────────────────────

type putWriter struct {
	stream workspacev1.WorkspaceService_PutClient
	name   string
}

func (w *putWriter) Write(p []byte) (int, error) {
	total := 0
	for len(p) > 0 {
		n := len(p)
		if n > putChunkSize {
			n = putChunkSize
		}
		chunk := make([]byte, n)
		copy(chunk, p[:n])
		if err := w.stream.Send(&workspacev1.PutRequest{
			Data: &workspacev1.PutRequest_Chunk{Chunk: chunk},
		}); err != nil {
			return total, fmt.Errorf("wsfs/remote: send chunk for %q: %w", w.name, err)
		}
		p = p[n:]
		total += n
	}
	return total, nil
}

func (w *putWriter) Close() error {
	if _, err := w.stream.CloseAndRecv(); err != nil {
		return fmt.Errorf("wsfs/remote: close put stream for %q: %w", w.name, err)
	}
	return nil
}

// ─────────────────────────────────────────────────────────────
// getReader — server-side streaming reader for Get
// ─────────────────────────────────────────────────────────────

type getReader struct {
	stream workspacev1.WorkspaceService_GetClient
	buf    []byte // leftover bytes from the last received chunk
	done   bool
}

func (g *getReader) Read(p []byte) (int, error) {
	// Drain any buffered data from the previous chunk first.
	if len(g.buf) > 0 {
		n := copy(p, g.buf)
		g.buf = g.buf[n:]
		return n, nil
	}
	if g.done {
		return 0, io.EOF
	}
	resp, err := g.stream.Recv()
	if err == io.EOF {
		g.done = true
		return 0, io.EOF
	}
	if err != nil {
		return 0, fmt.Errorf("wsfs/remote: recv get chunk: %w", err)
	}
	n := copy(p, resp.Chunk)
	if n < len(resp.Chunk) {
		// Store the overflow for the next Read call.
		g.buf = make([]byte, len(resp.Chunk)-n)
		copy(g.buf, resp.Chunk[n:])
	}
	return n, nil
}

func (g *getReader) Close() error {
	g.done = true
	g.buf = nil
	return nil
}

// ─────────────────────────────────────────────────────────────
// helpers
// ─────────────────────────────────────────────────────────────

// mapGRPCError converts well-known gRPC status codes to wsfs sentinels.
func mapGRPCError(op, path string, err error) error {
	if err == nil {
		return nil
	}
	st, ok := status.FromError(err)
	if ok {
		switch st.Code() {
		case codes.NotFound:
			return fmt.Errorf("%w: %s", ErrNotExist, path)
		case codes.PermissionDenied:
			return fmt.Errorf("%w: %s %s", ErrPermission, op, path)
		}
	}
	return fmt.Errorf("wsfs/remote: %s %q: %w", op, path, err)
}

// timeFromUnix converts a Unix-seconds timestamp to time.Time.
func timeFromUnix(sec int64) time.Time {
	if sec == 0 {
		return time.Time{}
	}
	return time.Unix(sec, 0)
}

// compile-time interface checks
var _ FS = (*RemoteFS)(nil)
var _ ManifestFS = (*RemoteFS)(nil)
